def mask(text,original):
    """Mask complete coefficient/derivative slots before rendering, including final row."""
    c=constant(original)
    text=text.replace(latex(c/x),'@@DERIVATIVE@@')
    text=text.replace(latex(c),'@@COEFFICIENT@@')
