        correct=next(a[':answer/id'] for a in answers if a[':answer/value']==latex(constant(p)/x))
        rng.shuffle(answers)
        field={':answer-field/id':fid,':answer-field/key':key,':answer-field/type':':answer-field.type/'+kind,':answer-field/choices':answers}
